def append_to_builder():
    with open("scripts/build_mega39_b.py", "r", encoding="utf-8") as f:
        content = f.read()

    # Find where PLAB_TOPICS is defined and append
    plab_marker = "PLAB_TOPICS = ["
    amc_marker = "AMC_TOPICS = ["

    # Instead of string manipulation, let's inject PLAB_TOPICS += ... and AMC_TOPICS += ...
    insertion = f"\n\nPLAB_TOPICS += {repr(PLAB_ADDITIONAL)}\n\nAMC_TOPICS += {repr(AMC_ADDITIONAL)}\n\n"
    
    # Insert right before def main():
    target = "def main():"
    new_content = content.replace(target, insertion + target)

    with open("scripts/build_mega39_b.py", "w", encoding="utf-8") as f:
        f.write(new_content)

    print("Successfully appended additional topics to build_mega39_b.py!")

if __name__ == "__main__":
    append_to_builder()
